func:
// sensors/<device>/<sensor> and inference/<device>/result to one line of
// InfluxDB line protocol, as the core p4n4-iot flow stores them:
//   sensor_data,device=,sensor=  value (and unit)
//   inference,device=            anomaly_score, confidence, latency_ms, label
// Payloads: {"value": 23.4, "unit": "C"} or a bare number for readings, the
// ei-runner result object for inference. "timestamp" (ISO 8601 or epoch) is
// the reading's time; without one, the time it arrived here.
var token = env.get("INFLUXDB_TOKEN");
var org = env.get("INFLUXDB_ORG");
var bucket = env.get("INFLUXDB_BUCKET") || "raw_telemetry";
if (!token || !org) {
    node.error("INFLUXDB_TOKEN and INFLUXDB_ORG env vars must be set", msg);
    return null;
}

// Tags are device and sensor names: anything else would grow cardinality
var TAG = /^[a-z0-9_-]{1,64}$/;
function clean(s) { return String(s).replace(/[\r\n]+/g, " "); }
function escString(s) { return '"' + clean(s).replace(/[\\"]/g, "\\$&") + '"'; }
function num(v) { return typeof v === "number" && isFinite(v); }

var parts = (msg.topic || "").split("/");
var device = parts[1];
if (!TAG.test(device || "")) {
    node.warn("Ignored " + msg.topic + ": device id must match " + TAG);
    return null;
}
var data = msg.payload;
if (num(data)) data = { value: data };
if (!data || typeof data !== "object" || Array.isArray(data)) {
    node.warn("Ignored " + msg.topic + ": expected a JSON object or a number");
    return null;
}

var line;
if (parts[0] === "sensors") {
    if (!TAG.test(parts[2] || "") || !num(data.value)) {
        node.warn("Ignored " + msg.topic + ": expected sensors/<device>/<sensor> with a numeric value");
        return null;
    }
    var fields = ["value=" + data.value];
    if (typeof data.unit === "string") fields.push("unit=" + escString(data.unit));
    line = "sensor_data,device=" + device + ",sensor=" + parts[2] + " " + fields.join(",");
} else {
    var f = [];
    ["anomaly_score", "confidence", "latency_ms"].forEach(function (k) {
        if (num(data[k])) f.push(k + "=" + data[k]);
    });
    if (typeof data.label === "string") f.push("label=" + escString(data.label));
    if (!f.length) {
        node.warn("Ignored " + msg.topic + ": no inference fields");
        return null;
    }
    line = "inference,device=" + device + " " + f.join(",");
}
var at = typeof data.timestamp === "string" ? Date.parse(data.timestamp) : data.timestamp;
if (!num(at)) at = Date.now();
else if (at < 1e11) at = at * 1000;

msg.method = "POST";
msg.url = "http://influxdb:8086/api/v2/write?org=" + encodeURIComponent(org) +
    "&bucket=" + encodeURIComponent(bucket) + "&precision=ms";
msg.headers = { "Authorization": "Token " + token, "Content-Type": "text/plain; charset=utf-8" };
msg.payload = line + " " + Math.round(at);
return msg;

// An inference result above ANOMALY_THRESHOLD raises alerts/<device>/anomaly
// (QoS 1), which the ai layer's agent investigates. While a device's score
// stays high, it alerts again only after ALERT_HOLDOFF seconds; the agent
// merges alerts of one device and window into one investigation anyway.
var threshold = Number(env.get("ANOMALY_THRESHOLD") || 0.7);
var holdoff = Number(env.get("ALERT_HOLDOFF") || 60) * 1000;
var r = msg.payload;
var device = (msg.topic || "").split("/")[1];
if (!r || typeof r !== "object" || typeof r.anomaly_score !== "number") return null;
if (!/^[a-z0-9_-]{1,64}$/.test(device || "")) return null;
if (r.anomaly_score <= threshold) return null;

var last = context.get("lastAlert") || {};
var now = Date.now();
if (last[device] && now - last[device] < holdoff) return null;
last[device] = now;
context.set("lastAlert", last);

node.status({ fill: "red", shape: "dot", text: device + " " + r.anomaly_score });
return {
    topic: "alerts/" + device + "/anomaly",
    qos: 1,
    payload: {
        device: device,
        anomaly_score: r.anomaly_score,
        label: r.label || null,
        threshold: threshold,
        timestamp: r.timestamp || new Date(now).toISOString()
    }
};
